package etcd

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"log"
	"strings"
	"sync"
	"time"
	"unicode/utf8"

	"example.invalid/dilock/core"
	clientv3 "go.etcd.io/etcd/client/v3"
)

const identityScheme = "sha256-framed-utf8-v1"
const profile = "etcd-native-lock-v1"

// ProviderOptions identifies compatible namespace metadata and the stable
// coordinator incarnation. Epoch must be provisioned and recognized by the
// protected resource; it is never generated by this SDK.
type ProviderOptions struct {
	Namespace, Epoch   string
	DefaultAcquisition dilock.AcquireOptions
	CleanupObserver    func(dilock.CleanupObservation)
}

// Provider borrows its etcd client and native Lock RPC. Close withdraws local
// lease reliance and performs bounded cleanup but does not close either client.
type Provider struct {
	client             Client
	locks              LockRPC
	ns                 string
	epoch              string
	defaultAcquisition dilock.AcquireOptions
	cleanupObserver    func(dilock.CleanupObservation)
	closeCtx           context.Context
	closeCancel        context.CancelFunc

	mu     sync.Mutex
	closed bool
	leases map[*Lease]struct{}
	ops    sync.WaitGroup
}

// NewProvider borrows a clientv3-compatible KV/lease client and an official
// native Lock RPC client. Both must point to the same etcd cluster. The caller
// retains both clients' lifetimes and closes them after Provider.Close.
func NewProvider(client Client, locks LockRPC, options ProviderOptions) (*Provider, error) {
	if client == nil || locks == nil {
		return nil, errors.New("etcd KV client and native Lock RPC are required")
	}
	if options.Namespace == "" {
		options.Namespace = "default"
	}
	if _, err := dilock.Identity(options.Namespace, "validation"); err != nil {
		return nil, err
	}
	if err := validateEpoch(options.Epoch); err != nil {
		return nil, err
	}
	closeCtx, closeCancel := context.WithCancel(context.Background())
	defaults, err := options.DefaultAcquisition.Normalized()
	if err != nil {
		closeCancel()
		return nil, err
	}
	return &Provider{client: client, locks: locks, ns: options.Namespace, epoch: options.Epoch,
		defaultAcquisition: defaults, cleanupObserver: options.CleanupObserver,
		closeCtx: closeCtx, closeCancel: closeCancel, leases: make(map[*Lease]struct{})}, nil
}

func (p *Provider) observeCleanup(outcome dilock.ReleaseOutcome, reason string) {
	observation := dilock.CleanupObservation{Backend: "etcd", Outcome: outcome, Reason: reason}
	if p.cleanupObserver != nil {
		func() { defer func() { _ = recover() }(); p.cleanupObserver(observation) }()
		return
	}
	log.Printf("dilock etcd scope cleanup outcome=%d reason=%s", outcome, reason)
}

func validateEpoch(epoch string) error {
	if len(epoch) == 0 || len(epoch) > 1024 || !utf8.ValidString(epoch) || strings.IndexByte(epoch, 0) >= 0 {
		return fmt.Errorf("invalid coordination epoch")
	}
	return nil
}

// LockName returns the draft 1 native Lock name for a validated resource.
func LockName(namespace, resource string) (string, error) {
	id, err := dilock.Identity(namespace, resource)
	if err != nil {
		return "", fmt.Errorf("etcd lock name: %w", err)
	}
	return "/dilock/locks/" + id, nil
}

// Lock validates a resource and returns a reusable handle without network I/O.
func (p *Provider) Lock(resource string) (*Handle, error) {
	p.mu.Lock()
	defer p.mu.Unlock()
	if p.closed {
		return nil, dilock.ErrProviderClosed
	}
	name, err := LockName(p.ns, resource)
	if err != nil {
		return nil, err
	}
	return &Handle{provider: p, name: name}, nil
}

func (p *Provider) begin() bool {
	p.mu.Lock()
	defer p.mu.Unlock()
	if p.closed {
		return false
	}
	p.ops.Add(1)
	return true
}

func (p *Provider) addLease(l *Lease) bool {
	p.mu.Lock()
	defer p.mu.Unlock()
	if p.closed {
		return false
	}
	p.leases[l] = struct{}{}
	return true
}

func (p *Provider) removeLease(l *Lease) {
	p.mu.Lock()
	delete(p.leases, l)
	p.mu.Unlock()
}

// Close prevents new operations, waits for in-flight calls to settle, withdraws
// active local reliance and gives each acquired lease a fresh bounded cleanup
// budget. It does not close borrowed clients.
func (p *Provider) Close() error {
	p.mu.Lock()
	if p.closed {
		p.mu.Unlock()
		return nil
	}
	p.closed = true
	p.mu.Unlock()
	p.closeCancel()
	p.ops.Wait()
	p.mu.Lock()
	leases := make([]*Lease, 0, len(p.leases))
	for lease := range p.leases {
		leases = append(leases, lease)
	}
	p.mu.Unlock()
	for _, lease := range leases {
		lease.markLost("provider_shutdown")
		ctx, cancel := context.WithTimeout(context.Background(), lease.options.CleanupTimeout)
		_, _ = lease.Release(ctx)
		cancel()
	}
	return nil
}

func (p *Provider) metadata(ctx context.Context, timeout time.Duration) error {
	ctx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()
	key := "/dilock/namespaces/" + p.ns + "/meta"
	resp, err := p.client.Get(ctx, key) // Get is linearizable unless WithSerializable is supplied.
	if err != nil {
		if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
			return err
		}
		return backendError("etcd metadata read failed", err)
	}
	if resp == nil || resp.Count != 1 || len(resp.Kvs) != 1 || string(resp.Kvs[0].Key) != key || len(resp.Kvs[0].Value) == 0 || len(resp.Kvs[0].Value) > 8192 {
		return dilock.ErrProtocolMismatch
	}
	var fields map[string]json.RawMessage
	if err := json.Unmarshal(resp.Kvs[0].Value, &fields); err != nil {
		return dilock.ErrProtocolMismatch
	}
	if hasDuplicateTopLevelJSONField(resp.Kvs[0].Value) {
		return dilock.ErrProtocolMismatch
	}
	for _, required := range []string{"protocol_major", "identity_scheme", "profile", "coordination_epoch", "fixed_lease_ms"} {
		if _, ok := fields[required]; !ok {
			return dilock.ErrProtocolMismatch
		}
	}
	var value struct {
		ProtocolMajor  int    `json:"protocol_major"`
		IdentityScheme string `json:"identity_scheme"`
		Profile        string `json:"profile"`
		Epoch          string `json:"coordination_epoch"`
		FixedLeaseMS   *int64 `json:"fixed_lease_ms"`
	}
	dec := json.NewDecoder(strings.NewReader(string(resp.Kvs[0].Value)))
	if err := dec.Decode(&value); err != nil {
		return dilock.ErrProtocolMismatch
	}
	if err := dec.Decode(&struct{}{}); err != io.EOF {
		return dilock.ErrProtocolMismatch
	}
	if value.ProtocolMajor != 1 || value.IdentityScheme != identityScheme || value.Profile != profile || value.Epoch != p.epoch || value.FixedLeaseMS != nil || string(fields["fixed_lease_ms"]) != "null" {
		return dilock.ErrProtocolMismatch
	}
	return nil
}

func backendError(message string, cause error) error {
	return &dilock.OperationError{Kind: dilock.ErrBackendUnavailable, Message: message, Cause: cause}
}

func acquisitionUnknown(message string, cause error) error {
	return &dilock.OperationError{Kind: dilock.ErrAcquisitionUnknown, Message: message, Cause: cause}
}

func (p *Provider) revoke(id clientv3.LeaseID, timeout time.Duration) error {
	return p.revokeUntil(id, cleanupDeadline(timeout))
}

func (p *Provider) revokeUntil(id clientv3.LeaseID, deadline time.Time) error {
	remaining, ok := remainingCleanup(deadline)
	if !ok {
		return acquisitionUnknown("etcd lease revoke was not attempted before the cleanup deadline", context.DeadlineExceeded)
	}
	ctx, cancel := context.WithTimeout(context.Background(), remaining)
	defer cancel()
	_, err := p.client.Revoke(ctx, id)
	if err != nil {
		return backendError("etcd lease revoke was not acknowledged", err)
	}
	return nil
}
